<template>
  <section class="flex flex-col gap-3">
    <PageTitle title="Notifications" />
    <div class="flex flex-wrap items-center justify-between gap-2">
      <NotificationListFilters :params="params" />
      <div class="flex items-center gap-2">
        <NotificationSettings />
        <NotificationListActions @update="refetch" />
      </div>
    </div>
    <AppLoader v-if="isLoading && showLoader" variant="inline" subject="notifications" />
    <AppError
      v-else-if="error"
      :error="error"
      title="Failed to load notifications"
      variant="table"
      :action="refetch"
      action-text="Retry"
    />
    <AppEmpty
      v-else-if="!notificationData || notificationData.notifications.length === 0"
      subject="notifications"
      variant="table"
    />
    <div v-else class="flex flex-col gap-3">
      <NotificationListItem
        v-for="item in notificationData.notifications"
        :key="item.id"
        :data="item"
        @read="silentRefetch"
      />
      <AppPagination
        v-if="notificationData.total_count > 0"
        :page="params.page"
        :size="params.size"
        :total="notificationData.total_count"
        label="notifications"
      />
    </div>
  </section>
</template>

<script setup lang="ts">
import { notificationsList, type NotificationsListResponse, type SortType } from '~/client';

definePageMeta({
  backLabel: 'notifications',
});

useHead({
  title: 'Notifications',
});

const route = useRoute();

const params = computed(() => {
  const urlParams = {
    page: Number(route.query.page) || 1,
    size: Number(route.query.size) || 10,
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
    only_unread: route.query.only_unread === 'true',
  };

  return Object.fromEntries(Object.entries(urlParams).filter(([_, value]) => value !== undefined)) as typeof urlParams;
});

const showLoader = ref(true);

const {
  data: notificationData,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['notifications-list', params.value],
  query: (): Promise<NotificationsListResponse> =>
    notificationsList({
      composable: '$fetch',
      query: params.value,
    }),
  staleTime: 0,
});

async function silentRefetch() {
  showLoader.value = false;
  await refetch();
  showLoader.value = true;
}
</script>
