import { type GetUnreadNotificationsCountResponse } from '~/client';

export function updateNotificationCounter(number: number) {
  useQueryCache().setQueryData<GetUnreadNotificationsCountResponse | undefined>(
    ['unreadNotificationCount'],
    (prevData) => {
      if (!prevData) return prevData;

      if (prevData.count === undefined || prevData.count === null) return prevData;

      return {
        ...prevData,
        count: Math.max(0, prevData.count + number),
      };
    }
  );
}

export function setNotificationCounter(number: number) {
  useQueryCache().setQueryData<GetUnreadNotificationsCountResponse | undefined>(
    ['unreadNotificationCount'],
    (prevData) => {
      if (!prevData) return prevData;

      if (prevData.count === undefined || prevData.count === null) return prevData;

      return {
        ...prevData,
        count: number,
      };
    }
  );
}
