<template>
  <Item class="rounded-lg border border-border bg-card text-card-foreground shadow-sm flex-nowrap">
    <ItemMedia variant="default" :tone="typeData.variant as ItemMediaVariants['tone']">
      <component :is="typeData.icon" />
    </ItemMedia>
    <ItemContent>
      <ItemTitle class="sm:justify-end w-full flex-wrap sm:flex-nowrap gap-y-1">
        <div class="sm:flex-auto text-nowrap">{{ typeData.label }}</div>
        <Badge v-if="!isNotificationRead" variant="info" class="size-3 shrink-0 rounded-full px-1" />
        <div class="w-full sm:w-fit">
          <ItemDescription class="text-xs md:text-right text-nowrap">{{
            formatDateTzToFormat(notificationData.sent_at, 'MM/dd/yyyy, hh:mm aaa', timezone)
          }}</ItemDescription>
        </div>
      </ItemTitle>
      <ItemDescription class="line-clamp-none text-wrap">
        {{ notificationContent }}
      </ItemDescription>
      <ItemFooter v-if="buttons.length > 0" class="justify-normal gap-1 pt-2">
        <template v-for="(button, index) in buttons" :key="button.name">
          <Separator v-if="index > 0" orientation="vertical" class="h-4" />
          <Button
            variant="link"
            class="py-0 px-2 h-5"
            :class="button.class"
            :loading="button.loading"
            @click="button.onClick"
          >
            {{ button.content }}
          </Button>
        </template>
      </ItemFooter>
    </ItemContent>
  </Item>
</template>

<script lang="ts" setup>
import type { HTMLAttributes } from 'vue';
import { type NotificationShortInfo, markAsRead } from '~/client';
import type { ItemMediaVariants } from '~/components/ui/item';
import { getNotificationType } from '~/constants/notifications/notificationStatuses';
import { updateNotificationCounter } from '~/utils/notificationCounter';

const router = useRouter();

const { timezone } = useUserRole();

interface Props {
  data: NotificationShortInfo;
}

const props = defineProps<Props>();

interface Emits {
  (e: 'read'): void;
}

const emits = defineEmits<Emits>();

const notificationData = ref(props.data);
const typeData = computed(() => getNotificationType(notificationData.value.type_));

const isNotificationRead = computed(() => notificationData.value.read_at !== null);
const notificationContent = computed(() => notificationData.value.message ?? typeData.value.short_description);
const redirectsTo = computed(
  () => notificationData.value.relative_url ?? typeData.value.redirect?.to(notificationData.value)
);
const redirectsLabel = computed(() => typeData.value.redirect?.label ?? 'Details');

const useMarkAsRead = defineMutation(() => {
  const { mutateAsync: markAsReadMutation, asyncStatus } = useMutation({
    mutation: () =>
      markAsRead({
        composable: '$fetch',
        path: {
          notification_id: props.data.id,
        },
      }),
    onSuccess: () => {
      updateNotificationCounter(-1);
      notificationData.value = { ...notificationData.value, read_at: new Date().toISOString() };
      emits('read');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    markAsReadMutation,
    isLoading: computed(() => asyncStatus.value === 'loading'),
  };
});

const { markAsReadMutation, isLoading } = useMarkAsRead();

function handleMarkAsReadClick() {
  markAsReadMutation();
}

function handleRedirectClick() {
  if (!isNotificationRead.value) {
    markAsReadMutation();
  }
  if (redirectsTo.value) {
    router.push(redirectsTo.value);
  }
}

const buttons = computed(() => {
  const buttons_: {
    name: string;
    onClick: () => void;
    content: string;
    class: HTMLAttributes['class'];
    loading?: boolean;
  }[] = [];

  if (redirectsTo.value && redirectsLabel.value) {
    buttons_.push({
      name: 'Redirect',
      onClick: handleRedirectClick,
      content: `Go to ${redirectsLabel.value}`,
      class: '',
    });
  }

  if (!isNotificationRead.value) {
    buttons_.push({
      name: 'MarkAsRead',
      onClick: handleMarkAsReadClick,
      content: 'Mark as read',
      class: 'font-normal',
      loading: isLoading.value,
    });
  }

  if (buttons_.length > 0) {
    buttons_[0].class = buttons_[0].class.concat(' pl-0');
  }

  return buttons_;
});
</script>
