<template>
  <div class="flex items-center justify-end">
    <Button :loading="isLoading" @click="applyClick"> Read All </Button>
  </div>
</template>

<script setup lang="ts">
import { markAllAsRead } from '~/client';
import { setNotificationCounter } from '~/utils/notificationCounter';

interface Emits {
  (e: 'update'): void;
}

const emit = defineEmits<Emits>();

const useMarkAllAsRead = defineMutation(() => {
  const { mutateAsync: markAllAsReadMutation, asyncStatus } = useMutation({
    mutation: () =>
      markAllAsRead({
        composable: '$fetch',
      }),
    onSuccess: () => {
      setNotificationCounter(0);
      showToastSuccess('Marked all as read');
      emit('update');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    markAllAsReadMutation,
    isLoading: computed(() => asyncStatus.value === 'loading'),
  };
});

const { markAllAsReadMutation, isLoading } = useMarkAllAsRead();

function applyClick() {
  markAllAsReadMutation();
}
</script>
