<template>
  <Popover v-if="isNative">
    <PopoverTrigger as-child>
      <Button
        variant="outline"
        size="icon"
        aria-label="Notification settings"
        data-testid="notifications-settings-button"
      >
        <SettingsIcon />
      </Button>
    </PopoverTrigger>
    <PopoverContent align="end" class="w-80 p-4" data-testid="notifications-settings-popover">
      <NotificationPushToggle />
    </PopoverContent>
  </Popover>
</template>

<script setup lang="ts">
import { App as CapacitorApp } from '@capacitor/app';
import type { PluginListenerHandle } from '@capacitor/core';
import { SettingsIcon } from 'lucide-vue-next';
import { useMobilePushNotifications } from '~/composables/mobile/useMobilePushNotifications';

const { isNative, refresh } = useMobilePushNotifications();

let resumeListener: PluginListenerHandle | null = null;

onMounted(async () => {
  if (!isNative) return;
  await refresh();
  // Re-sync when returning from the system Settings (e.g. after the user flips
  // the OS permission on/off there), so the switch reflects the real state.
  resumeListener = await CapacitorApp.addListener('resume', () => {
    refresh();
  });
});

onUnmounted(() => {
  resumeListener?.remove();
  resumeListener = null;
});
</script>
