import type { HttpOptions } from '@capacitor/core';
import type { NotificationTokenResponse, UnregisterFcmTokenData } from '~/client';
import { doNativeRequest } from '~/utils/mobile/doNativeRequest';

export async function unregisterNotificationToken(
  query: UnregisterFcmTokenData['query']
): Promise<NotificationTokenResponse> {
  const url: UnregisterFcmTokenData['url'] = '/api/mobile/notifications/token';
  const options: HttpOptions = {
    url,
    method: 'DELETE',
    params: query,
  };
  return doNativeRequest<NotificationTokenResponse>(options, 'NotificationToken');
}
