<template>
  <div class="flex gap-2 items-center bg-card py-1 px-3 rounded-lg">
    <Label v-if="label" class="text-nowrap">{{ label }}</Label>
    <Switch :model-value="value" @update:model-value="toggle" />
  </div>
</template>

<script setup lang="ts">
interface Props {
  label?: string;
  value: boolean;
  propertyName: string;
  isFirstPageOnly?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  label: undefined,
  isFirstPageOnly: true,
});

const emit = defineEmits(['change']);

const route = useRoute();

async function toggle() {
  const propertyObject: Record<string, string | undefined> = {};
  propertyObject[props.propertyName] = `${!props.value}`;
  await navigateTo({
    name: route.name,
    params: route.params,
    query: {
      ...route.query,
      ...(props.isFirstPageOnly ? { page: 1 } : {}),
      ...propertyObject,
    },
  });
  emit('change');
}
</script>
