const defaultNotificationType: NotificationTypeEntry = {
  icon: Info,
  label: '',
  variant: 'default',
  title: '',
  short_description: '',
  redirect: null,
};

export function getNotificationType(type: NotificationType): NotificationTypeEntry {
  return (
    notificationTypeConfig[type] ?? {
      ...defaultNotificationType,
      label: snakeCaseToCapitalizedCase(type),
      title: snakeCaseToCapitalizedCase(type),
    }
  );
}
