import { Capacitor } from '@capacitor/core';
import { FirebaseMessaging } from '@capacitor-firebase/messaging';
import type { PermissionState } from '@capacitor/core';
import { openAppSettings } from '~/composables/mobile/useMobilePermissions';
import {
  isRegistered,
  isNotificationsPermitted,
  requestAndRegisterPushNotifications,
  deleteTokenIfExists,
} from '~/plugins/notifications';
import { useDeviceInfoStore } from '~/stores/mobile/deviceInfo';
import { getPushDisabledByUser, setPushDisabledByUser } from '~/utils/mobile/pushNotificationPrefs';
import { unregisterNotificationToken } from '~/mutations/mobile/unregisterPushNotificationsToken';
import { sendUpdateDeviceInfo } from '~/utils/mobile/updateDeviceInfo';

const _permission = ref<PermissionState | null>(null);
const _userDisabled = ref<boolean>(false);
const _busy = ref<boolean>(false);

export function useMobilePushNotifications() {
  const isNative = Capacitor.isNativePlatform();

  const permission = _permission;
  const busy = _busy;

  // Push is on only when the OS granted it AND the user hasn't opted out.
  const enabled = computed(() => _permission.value === 'granted' && !_userDisabled.value);

  async function refresh() {
    if (!isNative) return;
    _userDisabled.value = await getPushDisabledByUser();
    const { receive } = await FirebaseMessaging.checkPermissions();
    _permission.value = receive;
    isNotificationsPermitted.value = receive === 'granted';
  }

  async function enable() {
    if (!isNative) return;

    let status = _permission.value ?? (await FirebaseMessaging.checkPermissions()).receive;

    // Permission was previously denied — the app cannot re-prompt, so send the
    // user to the system settings to flip it on manually.
    if (status === 'denied') {
      await openAppSettings();
      return;
    }

    // Not yet decided — ask the OS now.
    if (status !== 'granted') {
      const { receive } = await FirebaseMessaging.requestPermissions();
      status = receive;
      _permission.value = receive;
    }

    if (status !== 'granted') return;

    // The opt-out preference must be cleared before registering — registration
    // paths are gated on it — but only stays cleared if registration completes.
    await setPushDisabledByUser(false);
    _userDisabled.value = false;
    isNotificationsPermitted.value = true;

    try {
      await requestAndRegisterPushNotifications();
    } finally {
      // requestAndRegisterPushNotifications swallows sync failures, so success is
      // observable only via isRegistered. Roll back the opt-out preference on
      // failure — otherwise the switch shows ON while no token is registered.
      if (!isRegistered.value) {
        await setPushDisabledByUser(true);
        _userDisabled.value = true;
      }
    }

    if (!isRegistered.value) {
      throw new Error('Push notification token registration did not complete');
    }
  }

  async function disable() {
    if (!isNative) return;

    await setPushDisabledByUser(true);
    _userDisabled.value = true;

    const deviceId = useDeviceInfoStore().info.id;
    if (deviceId) {
      try {
        await unregisterNotificationToken({ device_id: deviceId });
      } catch (e) {
        console.warn('[PushNotifications] Failed to unregister notification token:', e);
      }
    }

    try {
      await deleteTokenIfExists();
    } catch (e) {
      console.warn('[PushNotifications] Failed to delete FCM token:', e);
    }

    isRegistered.value = false;
    isNotificationsPermitted.value = false;
  }

  async function onToggle(value: boolean) {
    if (!isNative || _busy.value) return;
    _busy.value = true;
    try {
      try {
        if (value) {
          await enable();
        } else {
          await disable();
        }
      } catch (e) {
        console.error('[PushNotifications] Failed to toggle push notifications:', e);
        showToastError(`Failed to ${value ? 'enable' : 'disable'} push notifications`);
      }

      // Always re-read the real state so the switch reflects it even after a failure.
      await refresh();

      // Best-effort: report the new push state to the backend on every switch toggle.
      try {
        await sendUpdateDeviceInfo();
      } catch (e) {
        console.warn('[PushNotifications] Failed to sync device push state after toggle:', e);
      }
    } finally {
      _busy.value = false;
    }
  }

  return {
    isNative,
    permission,
    enabled,
    busy,
    refresh,
    enable,
    disable,
    onToggle,
  };
}
